def group_existing_cards(apps, schema_editor):
    Card = apps.get_model("reports", "StudentReportCard")
    Period = apps.get_model("reports", "ReportCardPeriod")
    alias = schema_editor.connection.alias
    # Historical files have no reliable academic year. Preserve them without guessing.
